function renderMD(md){var h=md.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
h=h.replace(/```([\s\S]*?)```/g,'<pre><code>$1</code></pre>');
h=h.replace(/`([^`]+)`/g,'<code>$1</code>');
h=h.replace(/^### (.+)$/gm,'<h3>$1</h3>');
h=h.replace(/^## (.+)$/gm,'<h2>$1</h2>');
h=h.replace(/^# (.+)$/gm,'<h1>$1</h1>');
h=h.replace(/^> (.+)$/gm,'<blockquote>$1</blockquote>');
h=h.replace(/^- (.+)$/gm,'<li>$1</li>');
h=h.replace(/(<li>[\s\S]*?<\/li>)+/g,'<ul>$&</ul>');
h=h.replace(/^\|.*\|\s*$/gm,function(row){var cells=row.split('|').slice(1,-1);var isSeparator=cells.every(function(c){return /^\s*[-:]+\s*$/.test(c);});if(isSeparator)return'';var htmlCells=cells.map(function(c){return'<td>'+c.trim()+'</td>';}).join('');return'<tr>'+htmlCells+'</tr>';});
h=h.replace(/(<tr>[\s\S]*?<\/tr>\s*)+/g,'<table class=\'md-table\'>$&</table>');
h=h.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
h=h.replace(/\*(.+?)\*/g,'<em>$1</em>');
h=h.replace(/\n\n+/g,'</p><p>');
return '<p>'+h+'</p>'.replace(/<p>\s*<\/p>/g,'');}
