function showEvalSummary(){var data=currentEvalData;var c=document.getElementById('preview-content');if(!data){c.innerHTML="<div class='preview-empty'><div class='preview-empty-icon'>&#9888;</div>Failed to load</div>";return;}var covColor=data.coverage>=50?'var(--success)':'var(--accent)';var uniprot=data.uniprot||{};var scores=data.scores||{};var scoresHtml='';for(var method in scores){var info=scores[method];var pct=info.score*10;var color=info.score>=7?'var(--success)':info.score>=5?'var(--accent)':'var(--danger)';scoresHtml+='<div style="margin-bottom:8px;"><div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:2px;"><span>'+method+'</span><span style="color:'+color+';font-weight:700;">'+info.score+'/10 '+info.assessment+'</span></div><div style="height:3px;background:var(--card);border-radius:2px;"><div style="height:3px;width:'+pct+'%;background:'+color+';border-radius:2px;"></div></div></div>';}c.innerHTML="<div class='report-meta'>"+'<div class="mr"><span class="ml">UniProt</span><span class="mv"><a href="https://www.uniprot.org/uniprot/'+data.uniprot_id+'" target="_blank" style="color:var(--primary);">'+data.uniprot_id+'</a></span></div>'+'<div class="mr"><span class="ml">Protein Name</span><span class="mv">'+escHtml(uniprot.protein_name||'N/A')+'</span></div>'+'<div class="mr"><span class="ml">Gene Name</span><span class="mv">'+escHtml((uniprot.gene_names||[]).join(', '))+'</span></div>'+'<div class="mr"><span class="ml">Organism</span><span class="mv">'+escHtml(uniprot.organism||'N/A')+'</span></div>'+'<div class="mr"><span class="ml">Sequence Length</span><span class="mv">'+(uniprot.sequence_length||0)+' aa</span></div>'+'<div class="mr"><span class="ml">Coverage</span><span class="mv" style="color:'+covColor+';font-weight:700;">'+(data.coverage||0)+'%</span></div>'+'<div class="mr"><span class="ml">PDB Structures</span><span class="mv">'+(data.pdb_structures||[]).length+'</span></div>'+'</div>'+'<h3 style="margin:10px 0 6px;font-size:12px;color:var(--primary);">Feasibility Score</h3><div style="padding:6px;background:var(--card);border-radius:6px;margin-bottom:8px;">'+scoresHtml+'</div>';}
function showEvalFullReport(){var data=currentEvalData;var c=document.getElementById('preview-content');if(!data){c.innerHTML="<div class='preview-empty'><div class='preview-empty-icon'>&#9888;</div>No data</div>";return;}var reportContent=(typeof data==='string')?data:(data.report||'');if(!reportContent){c.innerHTML="<div class='preview-empty'><div class='preview-empty-icon'>&#9888;</div>No full report available</div>";return;}c.innerHTML="<div class='md-content'>"+renderEvalMD(reportContent)+'</div>';}
var evalSearchTimer=null;document.getElementById('eval-search').addEventListener('input',function(e){clearTimeout(evalSearchTimer);evalSearchTimer=setTimeout(function(){activeEvalSearch=e.target.value.trim();loadEvalList();},300);});document.getElementById('eval-search').addEventListener('keydown',function(e){if(e.key==='Enter'){clearTimeout(evalSearchTimer);activeEvalSearch=e.target.value.trim();loadEvalList();loadEvalReports();}});
function sortEvalStructures(arr){var copy=arr.slice();for(var si=0;si<copy.length;si++){if(copy[si]._origIdx==null)copy[si]._origIdx=si;}return copy.sort(function(a,b){var col=sortCol;var av=a[col],bv=b[col];if(col==='journal_if'||col==='if'){av=(av==null||String(av).trim()===''||String(av).toLowerCase()==='unknown')?0:parseFloat(av);bv=(bv==null||String(bv).trim()===''||String(bv).toLowerCase()==='unknown')?0:parseFloat(bv);return sortAsc?(av-bv):(bv-av);}if(col==='resolution'){av=(av==null||String(av).trim()===''||isNaN(parseFloat(av)))?999:parseFloat(av);bv=(bv==null||String(bv).trim()===''||isNaN(parseFloat(bv)))?999:parseFloat(bv);return sortAsc?(av-bv):(bv-av);}var an=parseFloat(av),bn=parseFloat(bv);var aNum=(av!=null&&String(av).trim()!==''&&!isNaN(an));var bNum=(bv!=null&&String(bv).trim()!==''&&!isNaN(bn));var cmp;if(aNum&&bNum){cmp=an-bn;}else if(aNum){cmp=-1;}else if(bNum){cmp=1;}else{cmp=String(av||'').localeCompare(String(bv||''));}return sortAsc?cmp:-cmp;});}
document.getElementById('btn-mode-weekly').onclick=function(){setMode('weekly');};
