var activeEvalMethod='all';var activeEvalPdbSearch='';var filteredEvalStructures=[];
function filterEvalStructures(){if(!currentEvalStructures)return [];var filtered=currentEvalStructures.slice();if(activeEvalMethod!=='all'){filtered=filtered.filter(function(s){var m=(s.method||'').toLowerCase();if(activeEvalMethod==='cryoem')return /electron microscopy|cryo(?!.*crystallography)/i.test(m);if(activeEvalMethod==='electron_crystallography')return /electron crystallography/i.test(m);if(activeEvalMethod==='xray')return /x-ray|xray/i.test(m);if(activeEvalMethod==='nmr')return /nmr/i.test(m);return true;});}if(activeEvalPdbSearch){var q=activeEvalPdbSearch.toLowerCase();filtered=filtered.filter(function(s){var pdbId=(s.pdb_id||'').toLowerCase();var title=(s.title||'').toLowerCase();return pdbId.indexOf(q)>=0||title.indexOf(q)>=0;});}return filtered;}
function renderBlastHomologs(blastResults){
var section=document.getElementById('blast-homologs-section');
if(!blastResults||!blastResults.length){section.classList.remove('visible');section.innerHTML='';return;}
section.classList.add('visible');
var html='<div class="blast-section-header">&#128279; 同源蛋白 (BLAST)<span class="blast-count-badge">'+blastResults.length+'</span></div>';
html+='<div class="blast-table-container"><table class="blast-table"><thead><tr><th>PDB</th><th>Method</th><th>Res</th><th>IF</th><th>Identity</th><th>E-value</th><th>Description</th></tr></thead><tbody>';
for(var i=0;i<blastResults.length;i++){
var b=blastResults[i];
var pdbId=escHtml(b.pdb_id||'-');
var method=escHtml(b.method||'-');
var res=b.resolution!=null?b.resolution.toFixed(1)+' ':'-';
var jif=b.journal_if?'<span class="if-badge">'+b.journal_if.toFixed(1)+'</span>':'-';
var identityRaw=b.identity||0;var identityPct=b.query_coverage>0?Math.round((identityRaw/b.query_coverage)*100):identityRaw;var identity=identityPct>100?100:identityPct;
var evalue=b.evalue!=null?b.evalue.toExponential(1):'-';
var desc=escHtml((b.title||b.title||b.description||'').substring(0,80));
var idClass=identity>=70?'high':identity>=40?'mid':'low';
html+='<tr>';
html+='<td><span class="blast-pdb-link" data-pdb="'+pdbId+'">'+pdbId+'</span> <span class="homolog-badge">同源</span></td>';
html+='<td class="blast-method">'+method+'</td>';
html+='<td class="blast-res">'+res+'</td>';
html+='<td class="blast-if">'+jif+'</td>';
html+='<td><span class="blast-identity '+idClass+'">'+identity+'</span></td>';
html+='<td><span class="blast-evalue">'+evalue+'</span></td>';
html+='<td class="blast-desc" title="'+escHtml(b.title||b.description||'')+'">'+desc+'</td>';
html+='</tr>';
}
html+='</tbody></table></div>';
section.innerHTML=html;
section.querySelectorAll('.blast-pdb-link').forEach(function(el){el.onclick=function(){var pdb=el.getAttribute('data-pdb');if(pdb)showPdbPreview(pdb);};});
}
